(()=>{
'use strict';
const cfg=window.BK_DISCOVERY;if(!cfg||!window.location||!document.head)return;
const allowedAttribution=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','gclid','gbraid','wbraid','fbclid'];
const initial=new URL(window.location.href),attribution=new URLSearchParams();for(const k of allowedAttribution){const v=initial.searchParams.get(k);if(v&&v.length<=250)attribution.set(k,v)}
const root=new URL(cfg.base+'/');let booting=true,startedAt=-1,completedAt=-1;
function track(name,values={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:name,...values})}
function meta(key,value,property=false){let node=document.head.querySelector('meta['+(property?'property':'name')+'="'+key+'"]');if(!node){node=document.createElement('meta');node.setAttribute(property?'property':'name',key);document.head.appendChild(node)}node.setAttribute('content',value)}
function update(path,replaceUrl=true){const m=cfg.pages[path||'index.html'];if(!m)return;document.title=m.title;let canonical=document.head.querySelector('link[rel="canonical"]');if(canonical)canonical.href=m.url;for(const [key,val] of Object.entries({'og:title':m.title,'og:description':m.description,'og:url':m.url,'og:image':m.image,'og:image:secure_url':m.image,'og:image:alt':m.imageAlt}))meta(key,val,true);for(const [key,val] of Object.entries({'description':m.description,'twitter:title':m.title,'twitter:description':m.description,'twitter:image':m.card,'twitter:image:alt':m.imageAlt}))meta(key,val);if(replaceUrl&&window.location.origin===root.origin){const url=new URL(m.url);for(const [k,v] of attribution)url.searchParams.set(k,v);history.replaceState(null,'',url.pathname+url.search)}
 // Static JSON-LD remains authoritative for the loaded URL. Replace page-specific graph on client navigation.
 const data=document.head.querySelector('script[type="application/ld+json"]');if(data){try{const schema=JSON.parse(data.textContent),graph=schema['@graph']||[];const page=graph.find(x=>['WebPage','ProfilePage'].includes(x['@type']));if(page){page['@id']=m.url+'#page';page.url=m.url;page.name=m.title;page.description=m.description;page['@type']=path==='author.html'?'ProfilePage':'WebPage';if(path==='author.html')page.mainEntity={'@id':cfg.base+'/#creator'};else delete page.mainEntity}schema['@graph']=graph.filter(x=>!['Quiz','BreadcrumbList'].includes(x['@type']));data.textContent=JSON.stringify(schema)}catch{}}
}
async function share(){const q=typeof queue!=='undefined'?queue[position]:null;const path=q?cfg.questions[String(q.id)]?.path:'index.html',page=cfg.pages[path]||cfg.pages['index.html'];try{if(navigator.share){await navigator.share({title:page.title,url:page.url});track('share',{method:'native',content_type:q?'practice':'site'})}else if(navigator.clipboard){await navigator.clipboard.writeText(page.url);track('share',{method:'copy',content_type:q?'practice':'site'});const n=document.getElementById('sharestatus');if(n)n.textContent='この問題のURLをコピーしました。'}else{const n=document.getElementById('sharestatus');if(n)n.textContent=page.url}}catch(e){if(e.name!=='AbortError'){const n=document.getElementById('sharestatus');if(n)n.textContent=page.url}}}
function shareControl(){const host=document.getElementById('questionarea');if(!host||document.getElementById('sharepractice'))return;const wrap=document.createElement('div');wrap.className='share-practice';const button=document.createElement('button');button.className='textbtn';button.id='sharepractice';button.textContent='この問題を共有 ↗';button.onclick=share;wrap.appendChild(button);host.appendChild(wrap);const msg=document.createElement('p');msg.id='sharestatus';msg.className='discovery-status';msg.setAttribute('role','status');host.appendChild(msg)}
if(typeof navigate==='function'){
 const oldNavigate=navigate;navigate=function(view){oldNavigate(view);if(!booting){if(view==='profile')update('author.html');else if(view==='practice'&&queue[position])update(cfg.questions[String(queue[position].id)]?.path);else update('index.html')}};
 const oldRender=renderQuestion;renderQuestion=function(){oldRender();const q=queue[position];if(q){shareControl();if(!booting){update(cfg.questions[String(q.id)]?.path);const heading=document.querySelector('#practice h1, #practice .page-title');if(heading)heading.textContent=q.topic+'の演習'}}else if(!booting){update('index.html');const logs=state.log.slice(sessionStart);if(logs.length&&completedAt!==sessionStart){completedAt=sessionStart;track('practice_complete',{exam,unit:String(level),question_count:logs.length})}}};
 const oldAnswer=answer;answer=function(a){const n=state.log.length,q=queue[position];oldAnswer(a);if(state.log.length>n&&q){if(startedAt!==sessionStart){startedAt=sessionStart;track('practice_start',{exam,unit:String(level)})}track('answer_submit',{exam,unit:String(level),question_id:String(q.id),format:inputKind(q)})}};
 const oldSet=startExerciseSet;startExerciseSet=function(l,kind='recommended',topic=''){if(kind==='wrong')track('mistake_retry_start',{exam,unit:String(l)});oldSet(l,kind,topic)};
 const qid=document.body.dataset.question,route=document.body.dataset.discoveryRoute;
 if(route==='question'&&cfg.questions[qid]){const target=questions.find(q=>String(q.id)===qid);exam=target.exam;curriculumExam=exam;curriculumUnit=target.level;level=target.level;queue=[target];position=0;sessionStart=state.log.length;mode='practice';renderFilters();renderQuestion();navigate('practice')}
 else if(route==='profile'||window.location.hash==='#profile')navigate('profile');
 else{const requested=initial.searchParams.get('exam');if(requested&&catalogs[requested]){exam=requested;curriculumExam=exam;const unit=initial.searchParams.get('unit');level=catalogs[exam].units.find(x=>String(x)===unit)??state.targets[exam]??catalogs[exam].units[0];curriculumUnit=level;startExerciseSet(level);navigate('practice')}shareControl()}
 booting=false;
}
document.addEventListener('click',e=>{const link=e.target.closest?.('a[href]');if(!link)return;const url=new URL(link.href,window.location.href);if(url.origin===root.origin&&attribution.size){for(const [k,v] of attribution)if(!url.searchParams.has(k))url.searchParams.set(k,v);link.href=url.href}});
})();
